llamadas.contenido:
{
    "title": "Reserva y recogida de ejemplares en la Biblioteca Municipal de Villaficticia",
    "role": "Bibliotecaria o colaborador de la biblioteca",
    "action": "reservar, recoger y gestionar ejemplares",
    "benefit": "fomentar el uso y disfrute de la biblioteca por parte de las personas socias",
    "description": "El sistema permite que las personas socias resigan ejemplares de la biblioteca con un máximo de 3 reservas activas. Las reservas se gestionan según la prioridad de llegada y se asignan ejemplares disponibles según sea necesario. La persona socia recibe notificación cuando su ejemplar está bloqueado y listo para recogida, pudiendo cancelar o recolección de acuerdo con sus necesidades. A las reservas no recogidas en 48 horas se aplicarán penalizaciones.",
    "business_goal": "Mantener una alta utilización y satisfacción del servicio entre las personas socias de la biblioteca, garantizando el acceso a recursos educativos y culturales.",
    "scope_includes": [
        "Reservas de ejemplares",
        "Reserveyes para personas socias con carné vigente",
        "Gestión del orden de llegada de las reservas",
        "Bloqueo del ejemplar para recogida",
        "Notificación a la persona socia al ejemplar estar disponible",
        "Cancelación de reservas"
    ],
    "scope_excludes": [
        "Reservas de obras de referencia",
        "Prestamos de ejemplares",
        "Reservas de títulos que la persona ya ha prestado",
        "Reservas de títulos no disponibles",
        "Reservas de títulos de la colección infantil/junívera para personas sin carné infantil"
    ],
    "acceptance_criteria": [
        {
            "id": "CA-01",
            "title": "Reserva pendiente",
            "given": ["La persona socia está solicitando una reserva"], "when": ["su título está disponible"], "then": ["la reserva se inserta en la cola de reservas en estado pendiente"]
        },
        {
            "id": "CA-02",
            "title": "Reserva activa",
            "given": ["una persona socia tiene hasta 3 reservas activas"], "when": ["se realiza una nueva reserva"], "then": ["la reserva se añade al máximo permitido de 3"]
        },
        {
            "id": "CA-03",
            "title": "Exemplar bloqueado", "given": ["un ejemplar está reservado por una persona socia"], "when": ["la persona lleva 48 horas sin recoger el ejemplar"], "then": ["el ejemplar se bloquea para la persona socia"]
        },
        {
            "id": "CA-04",
            "title": "Exemplar recogido",
            "given": ["la persona socia recoge el ejemplar"], "when": ["el ejemplar está bloqueado"], "then": ["la reserva se convierte en préstamo"]
        },
        {
            "id": "CA-05",
            "title": "Reserva caducada",
            "given": ["pasa 48 horas sin que la persona socia reciba su ejemplar"], "when": ["ya no hay 48 horas activas restantes"], "then": ["la reserva se marca como caducada"]
        },
        {
            "id": "CA-06",
            "title": "Reserva cancelada",
            "given": ["la persona socia decide cancelar su reserva"], "when": ["antes de recoger el ejemplar"], "then": ["la reserva se elimina del sistema"]
        }
    ],
    "business_rules": [
        {
            "id": "RN-RES-01",
            "description": "Solo las personas socias con carné vigente y sin sanción activa pueden reservar ejemplares."
        },
        {
            "id": "RN-RES-02",
            "description": "Cada persona socia puede tener un máximo de 3 reservas activas."
        },
        {
            "id": "RN-RES-03",
            "description": "La reserva se hace sobre un título y una sede de recogida."
        },
        {
            "id": "RN-RES-04",
            "description": "Las reservas se atienden por orden de llegada."
        },
        {
            "id": "RN-RES-05",
            "description": "Al ejemplar estar disponible, se le notifica a la persona socia en cabeza de la cola."
        },
        {
            "id": "RN-RES-06",
            "description": "Si no se recoge el ejemplar en 48 horas, pasa a la persona siguiente de la cola."
        },
        {
            "id": "RN-RES-07",
            "description": "La persona socia puede cancelar la reserva antes de la recogida, sin penalizaciones."
        },
        {
            "id": "RN-RES-08",
            "description": "No se pueden volver a prestar ejemplares sujetos a reserva."
        },
        {
            "id": "RN-RES-09",
            "description": "No se pueden reservar obras de referencia ni títulos ya prestados por la persona socia."
        },
        {
            "id": "RN-RES-10",
            "description": "Personas con carné infantil pueden reservar únicamente de la colección infantil/junívera."
        },
        {
            "id": "RN-RES-11",
            "description": "La persona con carné infantil puede tener un máximo de 3 reservas activas de la colección infantil/junívera."
        },
        {
            "id": "RN-RES-12",
            "description": "Las personas con carné infantil pueden reservar títulos de la colección infantil/junívera, con el mismo límite de reservas de 3."
        },
        {
            "id": "RN-RES-13",
            "description": "Personas con carné infantil no pueden reservar títulos de ninguna otra colección."
        },
        {
            "id": "RN-RES-14",
            "description": "Las reservas de personas con carné infantil se aplican solo a la colección infantil/junívera."
        },
        {
            "id": "RN-RES-15",
            "description": "El máximo de ejemplares a préstamo simultáneo se establece en 8 por persona socia."
        },
        {
            "id": "RN-RES-16",
            "description": "El límite de ejemplares de cada tipo de material se establece en 8 para todos los socias, con excepciones para las personas con carné infantil."
        },
        {
            "id": "RN-RES-17",
            "description": "Las personas con carné infantil tienen 4 ejemplares máximos de su colección respectiva, no 8."
        },
        {
            "id": "RN-RES-18",
            "description": "El plazo de recogida para las reservas es de 48 horas después de que el ejemplar esté bloqueado."
        },
        {
            "id": "RN-RES-19",
            "description": "Las reservas no recogidas reiteradas llevarán al aplicar una sanción: se reducirá el máximo de reservas permitidas durante 30 días, o se impedirá nuevas reservas durante 15 días."
        }
    ],
    "assumptions": [
        "La persona socia tiene acceso al sistema de reservas de la biblioteca.",
        "La persona socia posee un carné válido de la Biblioteca Municipal de Villaficticia.",
        "La persona socia no está sujeta a alguna sanción activa que impida reservar.",
        "La reserva se realizará sobre un título que esté disponible en la biblioteca."
    ],
    "constraints": [
        "La persona socia no puede reservar títulos de obras de referencia o títulos ya prestados."
    ],
    "dependencies": [
        "El sistema de reservas depende del cumplimiento de las políticas de préstamo de la Biblioteca Municipal de Villaficticia."
    ],
    "alternate_flows": [
        "Una persona socia que no cumpla con las condiciones de préstamo (como no tener un carné válido o estar sujeta a sanción) no puede realizar una reserva.",
        "Si se cumplen las 3 reservas no recogidas reiteradas (para un socio con carné regular), se aplicará una sanción: se reducirá el máximo de reservas o se impedirán nuevas reservas durante 15 días."
    ],
    "exceptions": [
        "Si una persona con carné infantil intenta reservar un título de colección no infantil/junívera, será descalificada.",
        "Si una persona con carné infantil llega a sus límites de ejemplares máximos, solo podrán reservar títulos de la colección infantil/junívera."
    ],
    "related_features": [
        "El aviso sobre la reserva caducada incluirá el número de reservas no recogidas reiteradas para que la persona socia entienda la posible sanción.",
        "El límite de 8 ejemplares máximo no se aplica a las personas con carné infantil, que pueden tener 4 ejemplares de sus colecciones específicas."
    ],
    "priority": "Must",
    "open_questions": [
        "¿Cuál es el procedimiento para implementar la sanción debido a reservas no recogidas reiteradas (aplicar reducciones del número máximo de reservas o impedir nuevas reservas) según se decidió en el acta de la Comisión de Servicios Bibliotecarios de abril de 2026?",
        "¿Cómo se notifica a las personas socias que sus ejemplares han caducado de 48 horas?"
    ]
}

{
    "title": "Biblioteca de Villaficticia",
    "role": "Persona socia",
    "action": "Registrar",
    "benefit": "Registre un libro en la web para recogerlo.",
    "description": "Una interfaz para guardar ejemplares del archivo de libro de la Biblioteca Municipal de Villaficticia.",
    "business_goal": "Mejora en las herramientas digitales para usuarios.",
    "scope_includes": [
        "Registro en la web,"
        ],
    "scope_excludes": [
        "Prestamos en persona",
        "Prestamos en línea"
    ],
    "acceptance_criteria": [
        {
            "id": "CA-01",
            "title": "Registro exitoso",
            "given": ["Persona con carné válido"], "when": ["realizar el registro"], "then": ["el ejemplar es reservado en el sistema Web"]
        },
        {
            "id": "CA-02",
            "title": "Máximo de 3 reservas",
            "given": ["Persona socio"], "when": ["realiza un nuevo registro"], "then": ["solo se permite un máximo de 3 reservas activas para la persona"]
        }
    ],
    "business_rules": [
        {
            "id": "RN-001",
            "description": "Solo personas socias con carné válido pueden registrarse."
        },
        {
            "id": "RN-002",
            "description": "Una persona socio puede tener un máximo de 3 reservas activas."
        },
        {
            "id": "RN-003",
            "description": "Ni libros no disponibles, ni obras de referencia pueden registrarse."
        }
    ],
    "assumptions": [
        "La carné de la persona es válido y corresponde al usuario.",
        "El libro en el que se quiere registrarse está disponible."
    ],
    "constraints": [
        "Los libros no pueden solicitarse si ya existen otros en la cuenta."
    ],
    "dependencies": [
        "La funcionalidad del registro depende del sistema web de la biblioteca."
    ],
    "alternate_flows": [
        "Si el libro no está disponible, el registro se cancela."
    ],
    "exceptions": [
        "Ni libros de referencia ni los ya prestados pueden ser registrados."
    ],
    "related_features": [
        "Registro en línea."
    ],
    "priority": "Must",
    "open_questions": [
        "¿Cómo se gestionan los libros fuera de stock?"
    ]
}
